def evolved_fsdp_prefetch(shards, M, N_LAYERS, rank, world_size,
                          num_devices, cores_per_device, xm, torch, num_nodes=1):
    """Batch all-gathers maximally: group tensors of identical shape, one AG per group."""
    outs = [[None] * N_LAYERS for _ in range(M)]
    groups = {}
    for m in range(M):
        for L in range(N_LAYERS):
            t = shards[m][L]
            groups.setdefault(tuple(t.shape), []).append((m, L))
    for shp, items in groups.items():
        stacked = torch.stack([shards[m][L] for (m, L) in items], dim=0)
        gathered = xm.all_gather(stacked, dim=-1)
        for i, (m, L) in enumerate(items):
            outs[m][L] = gathered[i]
    return outs

def evolved_fsdp_prefetch(shards, M, N_LAYERS, rank, world_size,
                          num_devices, cores_per_device, xm, torch, num_nodes=1):
    """FSDP weights shared across microbatches: gather each layer ONCE, reuse for all m."""
    # Gather layer weights once (weights identical across microbatches).
    groups = {}
    for L in range(N_LAYERS):
        t = shards[0][L]
        groups.setdefault(tuple(t.shape), []).append(L)
    layer_out = [None] * N_LAYERS
    for shp, layers in groups.items():
        stacked = torch.stack([shards[0][L] for L in layers], dim=0)
        gathered = xm.all_gather(stacked, dim=-1)
        for i, L in enumerate(layers):
            layer_out[L] = gathered[i]
    outs = [[layer_out[L] for L in range(N_LAYERS)] for _ in range(M)]
    return outs
